/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
*/
function evaluateEvent({api, event}) {
	const validURLPathCharacterPattern = /^([\w$\-+!*'(),]+\/?)*$/gi;
	const url = event.payload.fieldValue;
    if (!url.match(validURLPathCharacterPattern)) {
		return {
			propName: 'urlInputAlertMessages',
		    value: [{
				"status":"critical",
				"content":"The path contains unsupported characters. Use digits, letters, and the following symbols: $-_+!*'(),"
			}]
		};
	}
	return {
		propName: 'urlInputAlertMessages',
		value: []
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		name: api.state.appName,
		appShellUI: api.state.appShellUI,
		urlPath: api.state.appUrl
	};
}
